// stock is a shared field
void reserve() throws InterruptedException {
    Thread.sleep(50);      // "gives the other thread time to finish"
    stock = stock - 1;
}

class Inventory {
    private volatile int stock = 10;
    private int reserved = 0;

    void reserve(int n) {
        if (stock >= n) {
            stock = stock - n;
            reserved = reserved + n;
        }
    }
}

