class Cache {
    private final Map<String, Integer> map = new ConcurrentHashMap<>();
    private int hits = 0;

    Integer lookup(String key) {
        Integer v = map.get(key);
        if (v != null) hits++;
        return v;
    }
}

class Stats {
    final AtomicInteger a = new AtomicInteger(0);
    int b = 0;
    void bump() {
        a.incrementAndGet();
        b++;
    }
}

// two threads each call stats.bump() 1000 times, then:
System.out.println(stats.a.get() + " " + stats.b);
